void fn0() {
  String str1 = "AGGTAB";
  String str2 = "GXTXAYB";

  List<String> lcs1 = str1.split('');
  List<String> lcs2 = str2.split('');

  int m = lcs1.length;
  int n = lcs2.length;
  List<List<int>> dp = List.generate(m + 1, (_) => List<int>.filled(n + 1, 0));

  for (int i = 1; i <= m; i++) {
    for (int j = 1; j <= n; j++) {
      if (lcs1[i - 1] == lcs2[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1] + 1;
      } else {
        dp[i][j] = (dp[i - 1][j] > dp[i][j - 1]) ? dp[i - 1][j] : dp[i][j - 1];
      }
    }
  }

  int lcsLen = dp[m][n];
  List<String> lcsChars = List<String>.filled(lcsLen, '');
  int i = m, j = n, k = lcsLen - 1;
  while (i > 0 && j > 0) {
    if (lcs1[i - 1] == lcs2[j - 1]) {
      lcsChars[k] = lcs1[i - 1];
      i--;
      j--;
      k--;
    } else if (dp[i - 1][j] > dp[i][j - 1]) {
      i--;
    } else {
      j--;
    }
  }
  String lcsStr = lcsChars.join('');

  print("String 1: $str1");
  print("String 2: $str2");
  print("Longest Common Subsequence: $lcsStr");
  print("Length: $lcsLen");
}

