List<int> fn0(List<int> p0, int p1) {
  var g = 0;
  for (var v in p0) {
    var a = g.abs();
    var b = v.abs();
    while (b != 0) {
      var t = a % b;
      a = b;
      b = t;
    }
    g = a;
  }
  var result = <int>[];
  for (var d = 1; d * d <= g; d++) {
    if (g % d == 0) {
      if (d >= p1) result.add(d);
      var other = g ~/ d;
      if (other != d && other >= p1) result.add(other);
    }
  }
  result.sort();
  return result;
}

List<String> fn0(String p0, int p1) {
  final counts = <String, int>{};
  for (final part in p0.split(';')) {
    final idx = part.indexOf(':');
    if (idx <= 0) continue;
    final name = part.substring(0, idx);
    final value = int.tryParse(part.substring(idx + 1));
    if (value == null) continue;
    counts[name] = (counts[name] ?? 0) + value;
  }
  final entries = counts.entries.where((e) => e.value >= p1).toList();
  entries.sort((a, b) {
    final c = b.value.compareTo(a.value);
    return c != 0 ? c : a.key.compareTo(b.key);
  });
  return entries.map((e) => '${e.key}(${e.value})').toList();
}
